#include <winsock2.h>
#include <ws2tcpip.h>
#endif
#include "httplib.h"
#include "json.hpp"
#include "../cpp/Network.h"
#include <fstream>
#include <iostream>
#include <map>
#include <mutex>
#include <ctime>
#include <sstream>
#include <cstdio>
#include <cctype>
