using json=nlohmann::json;
struct Location { std::string id,name; Network net; json logs=json::array(); };
static std::map<std::string,Location> locations;
static std::mutex stateMutex;
static std::string clean(const std::string&s){std::string r;for(size_t i=0;i<s.size();++i)if((s[i]>='a'&&s[i]<='z')||(s[i]>='A'&&s[i]<='Z')||(s[i]>='0'&&s[i]<='9')||s[i]=='-'||s[i]=='_')r+=char(tolower(s[i]));return r;}
static std::string stamp(){std::time_t t=std::time(NULL);char b[32];std::strftime(b,sizeof(b),"%Y-%m-%dT%H:%M:%S",std::localtime(&t));return b;}
static std::string fileFor(const std::string&id){return "data/locations/"+id+"/network.json";}
static bool deleted(const std::string&id){std::ifstream f(("data/locations/"+id+"/deleted").c_str());return f.good();}
static std::vector<std::string> locationFolders(){std::vector<std::string> out;
#ifdef _WIN32
 WIN32_FIND_DATAA fd;HANDLE h=FindFirstFileA("data/locations/*",&fd);if(h!=INVALID_HANDLE_VALUE){do{if((fd.dwFileAttributes&FILE_ATTRIBUTE_DIRECTORY)&&fd.cFileName[0]!='.')out.push_back(fd.cFileName);}while(FindNextFileA(h,&fd));FindClose(h);}
#else
 DIR*d=opendir("data/locations");if(d){struct dirent*e;while((e=readdir(d))!=NULL)if(e->d_name[0]!='.')out.push_back(e->d_name);closedir(d);}
#endif
 return out;}
static json networkJson(const Location&l){json d=json::array(),c=json::array();for(const auto&x:l.net.devices())d.push_back({{"id",x.id},{"name",x.name},{"type",x.type},{"status",x.down?"failed":"active"}});for(const auto&x:l.net.connections())c.push_back({{"id",x.id},{"source",x.source},{"target",x.target},{"latency",x.latency},{"status",x.down?"failed":"active"}});return {{"locationId",l.id},{"locationName",l.name},{"devices",d},{"connections",c},{"logs",l.logs}};}
static void save(const Location&l){std::string path=fileFor(l.id);
#ifdef _WIN32
 _mkdir("data");_mkdir("data\\locations");_mkdir(("data\\locations\\"+l.id).c_str());_mkdir(("data\\locations\\"+l.id+"\\logs").c_str());
#else
 mkdir("data",0755);mkdir("data/locations",0755);mkdir(("data/locations/"+l.id).c_str(),0755);
 mkdir(("data/locations/"+l.id+"/logs").c_str(),0755);
#endif
 std::ofstream f(path.c_str());if(f)f<<networkJson(l).dump(2);std::ofstream log(("data/locations/"+l.id+"/logs/events.json").c_str());if(log)log<<l.logs.dump(2);}
static void loadFile(Location&l){std::ifstream f(fileFor(l.id).c_str());if(!f)return;try{json j;f>>j;l.name=j.value("locationName",l.name);std::vector<Network::Device>d;std::vector<Network::Connection>c;std::vector<std::string>e;for(auto x:j.value("devices",json::array()))d.push_back(Network::Device{x.value("id",std::string()),x.value("name",std::string()),x.value("type",std::string("computer")),x.value("status",std::string("active"))=="failed"});for(auto x:j.value("connections",json::array()))c.push_back(Network::Connection{x.value("id",std::string()),x.value("source",std::string()),x.value("target",std::string()),x.value("latency",1),x.value("status",std::string("active"))=="failed"});l.logs=j.value("logs",json::array());l.net.load(d,c,e);}catch(...){} }
static void seed(Location&l,const std::string& kind){if(kind=="legacy"){const char*names[]={"Router1","Switch1","Switch2","Server1","Switch3","PC1","PC2"};const char*types[]={"router","switch","switch","server","switch","computer","computer"};for(int i=0;i<7;++i)l.net.addDevice(names[i],names[i],types[i]);l.net.addConnection("link1","Router1","Switch1",5);l.net.addConnection("link2","Router1","Switch2",7);l.net.addConnection("link3","Switch1","Server1",2);l.net.addConnection("link4","Switch2","Server1",4);l.net.addConnection("link5","Switch2","Switch3",3);l.net.addConnection("link6","Switch3","PC1",1);l.net.addConnection("link7","Switch3","PC2",1);return;}const char*types[]={"router","switch","server","computer","computer","printer","access-point"};const char* names[]={"Router1","Switch1","Server1","PC1","PC2","Printer1","AP1"};int n=7;for(int i=0;i<n;++i)l.net.addDevice(names[i],names[i],types[i]);int eid=1;auto edge=[&](const char*a,const char*b,int w){l.net.addConnection("link"+std::to_string(eid++),a,b,w);};if(kind=="school"){edge("Router1","Switch1",2);edge("Switch1","PC1",1);edge("Switch1","PC2",1);edge("Switch1","Server1",3);edge("Switch1","Printer1",2);edge("Router1","AP1",2);}else if(kind=="college"){l.net.addDevice("Router2","Router2","router");l.net.addDevice("Switch2","Switch2","switch");edge("Router1","Router2",4);edge("Router1","Switch1",2);edge("Router2","Switch2",2);edge("Switch1","PC1",1);edge("Switch1","Server1",3);edge("Switch2","PC2",1);edge("Switch2","Printer1",2);edge("Switch2","AP1",2);}else if(kind=="hospital"){l.net.addDevice("Router2","Router2","router");edge("Router1","Router2",2);edge("Router1","Switch1",1);edge("Router2","Switch1",1);edge("Switch1","Server1",1);edge("Switch1","PC1",2);edge("Switch1","PC2",2);edge("Switch1","Printer1",3);edge("Switch1","AP1",2);}else{edge("Router1","Switch1",2);edge("Switch1","PC1",1);edge("Switch1","PC2",1);edge("Switch1","Server1",2);edge("Switch1","Printer1",2);edge("Switch1","AP1",2);}}
static json stats(const Location&l){int failedD=0,failedC=0,routers=0,switches=0,computers=0,servers=0;for(auto&d:l.net.devices()){failedD+=d.down;routers+=d.type=="router";switches+=d.type=="switch";computers+=d.type=="computer";servers+=d.type=="server";}for(auto&c:l.net.connections())failedC+=c.down;int total=(int)l.net.devices().size();return {{"totalDevices",total},{"activeDevices",total-failedD},{"failedDevices",failedD},{"routers",routers},{"switches",switches},{"computers",computers},{"servers",servers},{"totalConnections",l.net.connections().size()},{"activeConnections",l.net.connections().size()-failedC},{"failedConnections",failedC},{"availability",total?100.0*(total-failedD)/total:100.0},{"components",l.net.components()}};}
static json error(const std::string&m){return {{"error",m}};}
int main(){
#ifdef _WIN32
 _mkdir("data");_mkdir("data\\locations");
#else
 mkdir("data/locations",0755);
#endif
 const char* ids[]={"legacy","school","college","office","hospital"};const char* names[]={"Legacy Network","School","College","Office","Hospital"};std::vector<std::string> all(ids,ids+5),folders=locationFolders();for(size_t i=0;i<folders.size();++i)if(std::find(all.begin(),all.end(),folders[i])==all.end())all.push_back(folders[i]);for(size_t i=0;i<all.size();++i){if(deleted(all[i]))continue;Location l;l.id=all[i];for(int k=0;k<5;++k)if(all[i]==ids[k])l.name=names[k];if(l.name.empty())l.name=all[i];loadFile(l);if(l.net.devices().empty()&&i<5){seed(l,all[i]);save(l);}locations[l.id]=l;}
 httplib::Server server;
 server.Get("/api/locations",[](const httplib::Request&,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);json a=json::array();for(auto&p:locations)a.push_back({{"id",p.first},{"name",p.second.name}});r.set_content(a.dump(),"application/json");});
 server.Get(R"(/api/locations/([a-zA-Z0-9_-]+))",[](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);auto i=locations.find(clean(q.matches[1]));if(i==locations.end()){r.status=404;r.set_content(error("Location not found").dump(),"application/json");return;}r.set_content(networkJson(i->second).dump(),"application/json");});
 server.Post("/api/locations",[](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);try{json b=json::parse(q.body);std::string id=clean(b.value("id",std::string())),name=b.value("name",std::string());if(id.empty()||name.empty()||locations.count(id)){r.status=400;r.set_content(error("Valid unique id and name required").dump(),"application/json");return;}std::remove(("data/locations/"+id+"/deleted").c_str());Location l;l.id=id;l.name=name;save(l);locations[id]=l;r.status=201;r.set_content(networkJson(l).dump(),"application/json");}catch(...){r.status=400;r.set_content(error("Invalid JSON body").dump(),"application/json");}});
 server.Put(R"(/api/locations/([a-zA-Z0-9_-]+))",[](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);std::string id=clean(q.matches[1]);auto i=locations.find(id);if(i==locations.end()){r.status=404;r.set_content(error("Location not found").dump(),"application/json");return;}try{i->second.name=json::parse(q.body).value("name",i->second.name);save(i->second);r.set_content(networkJson(i->second).dump(),"application/json");}catch(...){r.status=400;r.set_content(error("Invalid JSON body").dump(),"application/json");}});
 server.Delete(R"(/api/locations/([a-zA-Z0-9_-]+))",[](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);std::string id=clean(q.matches[1]);if(id=="legacy"){r.status=400;r.set_content(error("Legacy network is protected").dump(),"application/json");return;}if(!locations.erase(id)){r.status=404;r.set_content(error("Location not found").dump(),"application/json");return;}std::remove(fileFor(id).c_str());std::ofstream marker(("data/locations/"+id+"/deleted").c_str());marker<<"deleted";r.set_content("{\"ok\":true}","application/json");});
 auto getloc=[](const httplib::Request&q)->Location*{std::string id=clean(q.get_param_value("locationId"));auto i=locations.find(id);return i==locations.end()?NULL:&i->second;};
 server.Get("/api/network",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=404;r.set_content(error("Unknown locationId").dump(),"application/json");return;}r.set_content(networkJson(*l).dump(),"application/json");});
 server.Get("/api/statistics",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=404;r.set_content(error("Unknown locationId").dump(),"application/json");return;}r.set_content(stats(*l).dump(),"application/json");});
 server.Get("/api/logs",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=404;r.set_content(error("Unknown locationId").dump(),"application/json");return;}r.set_content(l->logs.dump(),"application/json");});
 server.Get("/api/devices",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=404;r.set_content(error("Unknown locationId").dump(),"application/json");return;}r.set_content(networkJson(*l)["devices"].dump(),"application/json");});
 server.Get("/api/connections",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=404;r.set_content(error("Unknown locationId").dump(),"application/json");return;}r.set_content(networkJson(*l)["connections"].dump(),"application/json");});
 server.Get("/api/critical-devices",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=404;r.set_content(error("Unknown locationId").dump(),"application/json");return;}auto c=l->net.critical();r.set_content(json({{"devices",c.devices},{"connections",c.connections}}).dump(),"application/json");});
 server.Get("/api/path",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);Network::Path p;if(!l||!l->net.shortestPath(q.get_param_value("source"),q.get_param_value("destination"),p)){r.status=l?404:400;r.set_content(error("No path or invalid location/devices").dump(),"application/json");return;}r.set_content(json({{"devices",p.devices},{"latency",p.latency},{"hops",p.devices.size()-1}}).dump(),"application/json");});
 server.Get("/api/alternative-paths",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}json out=json::array();for(const auto&p:l->net.alternativePaths(q.get_param_value("source"),q.get_param_value("destination")))out.push_back({{"devices",p.devices},{"latency",p.latency},{"hops",p.devices.size()-1}});r.set_content(out.dump(),"application/json");});
 server.Get("/api/reachable",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);std::vector<std::string>up,cut;if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}if(!l->net.reachable(q.get_param_value("source"),up,cut)){r.status=404;r.set_content(error("Source device is missing or down").dump(),"application/json");return;}r.set_content(json({{"reachable",up},{"disconnected",cut}}).dump(),"application/json");});
 server.Post("/api/devices",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}try{json b=json::parse(q.body);std::string id=clean(b.value("id",std::string())),name=b.value("name",std::string()),type=b.value("type",std::string("computer"));if(id.empty()||!l->net.addDevice(id,name,type)){r.status=400;r.set_content(error("Invalid or duplicate device").dump(),"application/json");return;}l->logs.push_back({{"id",l->logs.size()+1},{"timestamp",stamp()},{"type","device-added"},{"target",id},{"description","Added "+type+" "+name},{"status","success"}});save(*l);r.status=201;r.set_content(networkJson(*l).dump(),"application/json");}catch(...){r.status=400;r.set_content(error("Invalid JSON body").dump(),"application/json");}});
 server.Put(R"(/api/devices/([a-zA-Z0-9_-]+))",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}try{json b=json::parse(q.body);std::string id=q.matches[1];if(!l->net.editDevice(id,b.value("name",std::string()),b.value("type",std::string()))){r.status=404;r.set_content(error("Device not found or invalid fields").dump(),"application/json");return;}save(*l);r.set_content(networkJson(*l).dump(),"application/json");}catch(...){r.status=400;r.set_content(error("Invalid JSON body").dump(),"application/json");}});
 server.Delete(R"(/api/devices/([a-zA-Z0-9_-]+))",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}if(!l->net.deleteDevice(q.matches[1])){r.status=404;r.set_content(error("Device not found").dump(),"application/json");return;}save(*l);r.set_content(networkJson(*l).dump(),"application/json");});
 server.Post("/api/connections",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}try{json b=json::parse(q.body);std::string id=clean(b.value("id",std::string())),a=b.value("source",std::string()),z=b.value("target",std::string());int w=b.value("latency",1);if(id.empty()||!l->net.addConnection(id,a,z,w)){r.status=400;r.set_content(error("Invalid connection; endpoints must exist and link must be unique").dump(),"application/json");return;}l->logs.push_back({{"id",l->logs.size()+1},{"timestamp",stamp()},{"type","connection-added"},{"target",id},{"description","Connected "+a+" to "+z},{"status","success"}});save(*l);r.status=201;r.set_content(networkJson(*l).dump(),"application/json");}catch(...){r.status=400;r.set_content(error("Invalid JSON body").dump(),"application/json");}});
 server.Put(R"(/api/connections/([a-zA-Z0-9_-]+))",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}try{int latency=json::parse(q.body).value("latency",-1);if(!l->net.editConnection(q.matches[1],latency)){r.status=404;r.set_content(error("Connection not found or invalid latency").dump(),"application/json");return;}save(*l);r.set_content(networkJson(*l).dump(),"application/json");}catch(...){r.status=400;r.set_content(error("Invalid JSON body").dump(),"application/json");}});
 server.Delete(R"(/api/connections/([a-zA-Z0-9_-]+))",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}if(!l->net.deleteConnection(q.matches[1])){r.status=404;r.set_content(error("Connection not found").dump(),"application/json");return;}save(*l);r.set_content(networkJson(*l).dump(),"application/json");});
 auto failure=[&](const httplib::Request&q,httplib::Response&r,bool restore){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}try{json b=json::parse(q.body);std::string type=b.value("type",std::string("device")),id=b.value("id",std::string());bool ok=false;if(type=="connection")ok=restore?l->net.restoreConnection(id):l->net.failConnection(id);else ok=restore?l->net.restoreDevice(id):l->net.failDevice(id);if(!ok){r.status=404;r.set_content(error("Target not found or already in requested state").dump(),"application/json");return;}l->logs.push_back({{"id",l->logs.size()+1},{"timestamp",stamp()},{"type",restore?"restored":type+"-failed"},{"target",id},{"description",(restore?"Restored ":"Failed ")+id},{"status","success"}});save(*l);r.set_content(networkJson(*l).dump(),"application/json");}catch(...){r.status=400;r.set_content(error("Invalid JSON body").dump(),"application/json");}};
 server.Post("/api/simulate-failure",[&](const httplib::Request&q,httplib::Response&r){failure(q,r,false);});server.Post("/api/restore",[&](const httplib::Request&q,httplib::Response&r){failure(q,r,true);});
 server.Post("/api/restore-all",[&](const httplib::Request&q,httplib::Response&r){std::lock_guard<std::mutex>g(stateMutex);Location*l=getloc(q);if(!l){r.status=400;r.set_content(error("Unknown locationId").dump(),"application/json");return;}l->net.restoreAll();l->logs.push_back({{"id",l->logs.size()+1},{"timestamp",stamp()},{"type","restored-all"},{"target","*"},{"description","All failures restored"},{"status","success"}});save(*l);r.set_content(networkJson(*l).dump(),"application/json");});
 server.Get("/",[](const httplib::Request&,httplib::Response&r){std::ifstream f("frontend/index.html");if(!f){r.status=404;r.set_content("frontend is missing","text/plain");return;}std::stringstream s;s<<f.rdbuf();r.set_content(s.str(),"text/html");});
 server.Get(R"(/(style\.css|script\.js))",[](const httplib::Request&q,httplib::Response&r){std::string ext=q.matches[1];std::ifstream f(("frontend/"+ext).c_str());if(!f){r.status=404;return;}std::stringstream s;s<<f.rdbuf();r.set_content(s.str(),ext=="style.css"?"text/css":"application/javascript");});
 std::cout<<"Network Failure Analyzer REST API listening on http://localhost:8080\n";server.listen("0.0.0.0",8080);return 0;
}
